9	 * postcode's acceptable range is keyed by the city's region (via
10	 * {@link Owner#regionForCity(String)}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
11	 * city whose region is not in the range table (including the {@code "UNKNOWN"} region)
12	 * accepts any 4-digit postcode. Postcode format (exactly 4 digits) is enforced upstream
13	 * by the {@code @Pattern} constraint on the request DTO; this helper only range-checks an
14	 * already-well-formed postcode.
15	 */
16	final class OwnerPostcodes {
17	
18	    /** Region -> inclusive 4-digit postcode range {low, high}. */
19	    private static final Map<String, int[]> REGION_RANGES = Map.of(
20	        "NSW", new int[] {2000, 2099},
21	        "VIC", new int[] {3000, 3099},
22	        "QLD", new int[] {4000, 4099});
23	
24	    private OwnerPostcodes() {
25	    }
26	
27	    /**
28	     * Whether the (well-formed, 4-digit) postcode is valid for the given city. True when
29	     * the city's region has no known range (any 4-digit postcode is accepted), otherwise
30	     * true only when the postcode falls within that region's inclusive range.
31	     */
32	    static boolean isValidForCity(String postcode, String city) {
33	        int[] range = REGION_RANGES.get(Owner.regionForCity(city));
34	        if (range == null) {
35	            return true;
36	        }
37	        int value = Integer.parseInt(postcode);
38	        return value >= range[0] && value <= range[1];
39	    }
