163	    /**
164	     * The owner's initials: the upper-cased first letters of firstName and
165	     * lastName, dot-separated with a trailing dot (e.g. {@code "J.S."}).
166	     */
167	    @Transient
168	    public String getInitials() {
169	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
170	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
171	    }
172	
173	    /**
174	     * The owner's membership number, formatted {@code "<customerCode>-M<YY>"} where
175	     * YY is the last two digits of the registration date's year
176	     * (e.g. {@code "TOW-SMI-0007-M26"}). Derived from the owner's own fields; null when
177	     * either the customer code or registration date is absent.
178	     */
179	    @Transient
180	    public String getMembershipNumber() {
181	        if (this.customerCode == null || this.registrationDate == null) {
182	            return null;
183	        }
184	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
185	    }
186	
187	    /**
188	     * The owner's membership level: a number from 1 to 3 assigned at creation. Starts
189	     * at 1, gains 1 when an email address is present, gains a further 1 when the owner
190	     * has no namesakes ({@code namesakeCount} is 0), and is capped at 3 (level 4 is
191	     * reserved for tenure). Derived from the owner's own fields.
192	     */
193	    @Transient
194	    public Integer getMembershipLevel() {
195	        int level = 1;
196	        boolean hasEmail = this.email != null && !this.email.isBlank();
197	        if (hasEmail) {
198	            level++;
199	        }
200	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
201	        if (unique) {
202	            level++;
203	        }
204	        return Math.min(level, 3);
