207	    /**
208	     * Fixed city-to-region lookup table. Any city not listed derives locality
209	     * {@code "UNKNOWN"}.
210	     */
211	    private static final Map<String, String> CITY_REGION = Map.of(
212	        "Sydney", "NSW",
213	        "Melbourne", "VIC",
214	        "Brisbane", "QLD");
215	
216	    /**
217	     * The owner's locality: the canonical region derived from the city using the
218	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
219	     * {@code Brisbane->QLD}), or {@code "UNKNOWN"} when the city is not in the table.
