248	    /**
249	     * The owner's identity key: the single value that duplicate detection is expressed
250	     * through, formed as {@code normalizedTelephone + "|" + (email or empty) + "|" +
251	     * (householdId or empty)}. The telephone and email are already stored in their
252	     * normalized forms (E.164 and lower-cased), and the household id is empty for a solo
253	     * owner. Two owners are duplicates only when their whole identity keys are equal, so
254	     * two members of the same household with different telephones have distinct keys.
255	     * Derived from the owner's own fields.
256	     */
257	    @Transient
258	    public String getIdentityKey() {
259	        return identityKey(this.telephone, this.email, this.householdId);
