262	    /**
263	     * Composes an identity key from its already-normalized parts. The single place the
264	     * key's shape is defined, so the create-time duplicate check (which normalizes a
265	     * request's parts) and this entity's {@link #getIdentityKey()} cannot drift apart. A
266	     * null or blank part contributes an empty segment.
267	     */
268	    public static String identityKey(String normalizedTelephone, String normalizedEmail, String householdId) {
269	        return keyPart(normalizedTelephone) + "|" + keyPart(normalizedEmail) + "|" + keyPart(householdId);
270	    }
271	
272	    private static String keyPart(String value) {
273	        return (value == null || value.isBlank()) ? "" : value;
274	    }
